using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading;
namespace FrameScout {
 public sealed class DiagnosticRecord {public string Id,File,Directory,StartedUtc,CompletedUtc,Status;public int Frames;}
 public static class Diagnostics {
  static readonly object gate=new object();static readonly List<string> secrets=new List<string>();static readonly List<DiagnosticRecord> records=new List<DiagnosticRecord>();static readonly List<AnalysisTrace> active=new List<AnalysisTrace>();static StreamWriter journal;static int part;static string session;public static bool Enabled {get;private set;}public static string LastError {get;private set;}
  public static string Root {get{return Path.Combine(Settings.DataDirectory,"diagnostics");}}
  public static string LatestDirectory {get{lock(gate){if(session!=null)return session;try{return Util.Json().Deserialize<Dictionary<string,string>>(SharedText(Path.Combine(Root,"latest.json")))["Directory"];}catch{return null;}}}}
  public static void RegisterSecret(string value){if(string.IsNullOrEmpty(value))return;lock(gate)if(!secrets.Contains(value))secrets.Add(value);}
  public static string Redact(string text){if(text==null)return null;lock(gate){foreach(var secret in secrets.OrderByDescending(x=>x.Length)){text=text.Replace(secret,"[密钥已隐藏]");string escaped=Util.Json().Serialize(secret);if(escaped.Length>2)text=text.Replace(escaped.Substring(1,escaped.Length-2),"[密钥已隐藏]");}}text=Regex.Replace(text,@"(?i)Bearer\s+[A-Za-z0-9_.~+/=\-]+","Bearer [密钥已隐藏]");return Regex.Replace(text,@"\b(?:sk-[A-Za-z0-9_\-]{20,}|gh[pousr]_[A-Za-z0-9_]{20,}|github_pat_[A-Za-z0-9_]{20,})","[密钥已隐藏]");}
  internal static StreamWriter Writer(string file){return new StreamWriter(new FileStream(file,FileMode.Create,FileAccess.Write,FileShare.ReadWrite),new UTF8Encoding(false));}
  static void SaveJson(string file,object data){string temp=file+".tmp";File.WriteAllText(temp,Redact(Util.Json().Serialize(data)),new UTF8Encoding(false));if(File.Exists(file))File.Replace(temp,file,null);else File.Move(temp,file);}
  static string SharedText(string file){using(var stream=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var reader=new StreamReader(stream,Encoding.UTF8))return reader.ReadToEnd();}
  static IEnumerable<string> SharedLines(string file){using(var stream=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var reader=new StreamReader(stream,Encoding.UTF8)){string row;while((row=reader.ReadLine())!=null)yield return row;}}
  public static void Enable(bool enabled){lock(gate){if(Enabled==enabled)return;if(!enabled){Log("diagnostic.disabled",null);Enabled=false;if(journal!=null){journal.Dispose();journal=null;}return;}try{Directory.CreateDirectory(Root);session=Path.Combine(Root,DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,8));Directory.CreateDirectory(session);Directory.CreateDirectory(Path.Combine(session,"videos"));records.Clear();part=1;journal=Writer(Path.Combine(session,"events-0001.jsonl"));Enabled=true;LastError=null;SaveJson(Path.Combine(session,"session.json"),new {Schema=1,Version=typeof(Program).Assembly.GetName().Version.ToString(),StartedUtc=DateTime.UtcNow.ToString("o"),FrameNumbering="界面帧号从1开始，FrameIndex从0开始",OperatingSystem=Environment.OSVersion.ToString(),Runtime=Environment.Version.ToString(),Is64Bit=Environment.Is64BitProcess,CpuCores=Environment.ProcessorCount});SaveJson(Path.Combine(Root,"latest.json"),new {Directory=session,UpdatedUtc=DateTime.UtcNow.ToString("o")});SaveIndex();Log("diagnostic.enabled",null);}catch(Exception ex){Enabled=false;LastError=ex.Message;}}}
  static void SaveIndex(){if(session!=null)SaveJson(Path.Combine(session,"index.json"),records.ToArray());}
  public static void Log(string kind,object data){lock(gate){if(!Enabled||journal==null)return;try{if(journal.BaseStream.Position>16*1024*1024){journal.Dispose();journal=Writer(Path.Combine(session,"events-"+(++part).ToString("0000")+".jsonl"));}journal.WriteLine(Redact(Util.Json().Serialize(new {Utc=DateTime.UtcNow.ToString("o"),Thread=Thread.CurrentThread.ManagedThreadId,Event=kind,Data=data})));journal.Flush();}catch(Exception ex){LastError=ex.Message;}}}
  public static void Error(string kind,Exception ex){Log(kind,new {Error=ex==null?"未知异常":ex.ToString()});}
  internal static void WriteError(Exception ex){lock(gate)LastError=ex.Message;}
  public static AnalysisTrace BeginAnalysis(string file,Settings settings){if(!Enabled&&!settings.DiagnosticMode)return new AnalysisTrace();if(!Enabled)Enable(true);lock(gate){if(!Enabled)return new AnalysisTrace();try{var entry=new DiagnosticRecord{Id=Guid.NewGuid().ToString("N"),File=Path.GetFullPath(file),StartedUtc=DateTime.UtcNow.ToString("o"),Status="检测中"};string safe=Regex.Replace(Path.GetFileNameWithoutExtension(file),@"[^\p{L}\p{N}_\-]","_");safe=safe.Substring(0,Math.Min(35,safe.Length));entry.Directory=Path.Combine(session,"videos",safe+"-"+entry.Id.Substring(0,8));Directory.CreateDirectory(entry.Directory);records.Add(entry);SaveIndex();var trace=new AnalysisTrace(entry,settings);active.Add(trace);Log("analysis.started",new {entry.Id,entry.File,entry.Directory,Settings=settings});return trace;}catch(Exception ex){LastError=ex.Message;return new AnalysisTrace();}}}
  internal static void Finished(AnalysisTrace trace,string status,int frames){lock(gate){if(trace.Record==null)return;trace.Record.Status=status;trace.Record.Frames=frames;trace.Record.CompletedUtc=DateTime.UtcNow.ToString("o");active.Remove(trace);try{SaveIndex();}catch(Exception ex){LastError=ex.Message;}Log("analysis.finished",trace.Record);}}
  public static void Flush(){AnalysisTrace[] snapshot;lock(gate){if(journal!=null)journal.Flush();snapshot=active.ToArray();}foreach(var trace in snapshot)trace.Flush();}
  public static void Export(string destination){Flush();string source=Root;if(!Directory.Exists(source)||Directory.GetDirectories(source).Length==0)throw new IOException("尚未生成诊断日志，请先开启诊断并重检视频。");using(var zip=new ZipArchive(new FileStream(destination,FileMode.Create,FileAccess.Write,FileShare.None),ZipArchiveMode.Create)){foreach(var file in Directory.GetFiles(source,"*",SearchOption.AllDirectories).Where(x=>new[]{".json",".jsonl",".csv",".log",".txt"}.Contains(Path.GetExtension(x).ToLowerInvariant())&&!Path.GetFullPath(x).Equals(Path.GetFullPath(destination),StringComparison.OrdinalIgnoreCase)&&!new[]{"api.json","settings.json"}.Contains(Path.GetFileName(x).ToLowerInvariant()))){string name=file.Substring(source.Length+1).Replace('\\','/');var entry=zip.CreateEntry(name,CompressionLevel.Optimal);using(var input=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var output=entry.Open()){long remaining=input.Length;var buffer=new byte[65536];while(remaining>0){int n=input.Read(buffer,0,(int)Math.Min(buffer.Length,remaining));if(n==0)break;output.Write(buffer,0,n);remaining-=n;}}}}Log("diagnostic.exported",new {Destination=destination});}
  public static DiagnosticRecord[] Records(){var result=new List<DiagnosticRecord>();if(!Directory.Exists(Root))return result.ToArray();foreach(var folder in Directory.GetDirectories(Root))try{string index=Path.Combine(folder,"index.json");if(File.Exists(index))result.AddRange(Util.Json().Deserialize<DiagnosticRecord[]>(SharedText(index))??new DiagnosticRecord[0]);}catch{}return result.GroupBy(x=>x.Id).Select(x=>x.First()).OrderByDescending(x=>x.StartedUtc).ToArray();}
  public static string Explain(string video,int frameNumber){return Explain(video,frameNumber,null);}
  public static string Explain(string video,int frameNumber,string diagnosticId){if(frameNumber<1)return "帧号从1开始，请填写大于0的整数。";var all=Records();var exact=all.Where(x=>x.File.Equals(video,StringComparison.OrdinalIgnoreCase)).ToArray();var matches=(exact.Length>0?exact:all.Where(x=>Path.GetFileName(x.File).Equals(Path.GetFileName(video),StringComparison.OrdinalIgnoreCase)).ToArray()).OrderByDescending(x=>x.StartedUtc).ToArray();var record=diagnosticId==null?(matches.FirstOrDefault(x=>File.Exists(Path.Combine(x.Directory,"analysis.json")))??matches.FirstOrDefault()):matches.FirstOrDefault(x=>x.Id==diagnosticId);if(record==null)return "没有找到这个视频的诊断记录。请先开启诊断模式，再单独重新检测该视频。";int index=frameNumber-1;var lines=new List<string>{"视频："+record.File,"诊断ID："+record.Id,"检测状态："+record.Status,"帧号："+frameNumber+"（FrameIndex="+index+"）","记录目录："+record.Directory,""};string summary=Path.Combine(record.Directory,"analysis.json");if(File.Exists(summary)){var result=Util.Json().Deserialize<DiagnosticAnalysis>(SharedText(summary));if(index>=result.FrameCount)return "该次检测实际只有 "+result.FrameCount+" 帧。";lines.Add("检测参数："+Util.Json().Serialize(result.Settings));lines.Add("时间精度："+(result.EstimatedTimes?"按标称帧率估算":"实际解码时间戳"));foreach(var row in SharedLines(Path.Combine(record.Directory,"frame-times.csv")).Skip(1)){var cells=row.Split(',');if(int.Parse(cells[1])==index){lines.Add("该帧时间："+Util.Time(double.Parse(cells[2],Util.CI)));break;}}var hits=result.Findings.Where(f=>f.Frame<=index&&index<=f.EndFrame).ToArray();lines.Add(hits.Length==0?"最终结果：该帧未被列入最终异常区间。":"最终结果："+string.Join("；",hits.Select(f=>f.Kind+" / "+f.Level+" / "+f.Rule+" / 第"+(f.Frame+1)+"–"+(f.EndFrame+1)+"帧："+f.Detail)));lines.Add("范围说明："+result.Notice);}
   string failure=Path.Combine(record.Directory,"failure.json");if(File.Exists(failure)){lines.Add("检测失败/取消详情：");lines.Add(SharedText(failure));}
   string metrics=Path.Combine(record.Directory,"frame-metrics.csv");if(File.Exists(metrics)){lines.Add("\r\n当前帧及邻帧指标（比例为0–1）：");string header=SharedLines(metrics).FirstOrDefault();lines.Add(header);foreach(var row in SharedLines(metrics).Skip(1)){var cells=row.Split(',');int n;if(cells.Length>1&&int.TryParse(cells[1],out n)&&Math.Abs(n-index)<=1)lines.Add(row);}}
   string decisions=Path.Combine(record.Directory,"decisions.jsonl");if(File.Exists(decisions)){lines.Add("\r\n涉及该帧的规则计算与过滤：");int found=0;foreach(var row in SharedLines(decisions)){try{var map=Util.Json().Deserialize<Dictionary<string,object>>(row);int first=Convert.ToInt32(map["StartIndex"]),last=Convert.ToInt32(map["EndIndex"]);if(index>=first-1&&index<=last+1){lines.Add(row);found++;}}catch{}}if(found==0)lines.Add("该帧未形成候选；可对照 thresholds.json 与相邻差异指标判断未通过的门槛。");}string thresholds=Path.Combine(record.Directory,"thresholds.json");if(File.Exists(thresholds)){lines.Add("\r\n本次阈值：");lines.Add(SharedText(thresholds));}return string.Join("\r\n",lines);}
 }
 public sealed class DiagnosticAnalysis {public string File,Id,Notice;public int FrameCount;public bool EstimatedTimes;public Settings Settings;public VideoInfo Info;public Finding[] Findings;}
 public sealed class AnalysisTrace : IDisposable {
  readonly object gate=new object();StreamWriter metrics,decisions,ffmpeg;Settings settings;bool disposed;string writeError;public DiagnosticRecord Record {get;private set;}public bool Enabled {get{return Record!=null&&!disposed;}}public string Directory {get{return Record==null?null:Record.Directory;}}public string Id {get{return Record==null?null:Record.Id;}}
  public AnalysisTrace(){}public AnalysisTrace(DiagnosticRecord record,Settings settings){Record=record;this.settings=settings;metrics=Diagnostics.Writer(Path.Combine(Directory,"frame-metrics.csv"));metrics.WriteLine("FrameNumber,FrameIndex,ApproxSeconds,Difference,ChangedArea,DarkFraction,MeanLuminance,IsBlack,GenericBoundary,ReturnBoundary");decisions=Diagnostics.Writer(Path.Combine(Directory,"decisions.jsonl"));ffmpeg=Diagnostics.Writer(Path.Combine(Directory,"ffmpeg.log"));try{Meta("input.json",new {record.File,record.Id,record.StartedUtc,Settings=settings,Size=new FileInfo(record.File).Length,ModifiedUtc=File.GetLastWriteTimeUtc(record.File).ToString("o"),Fingerprint=Shell.Fingerprint(record.File)});}catch(Exception ex){Meta("input.json",new{record.File,record.Id,Settings=settings,Error=ex.Message});}}
  public void Meta(string name,object data){if(!Enabled)return;lock(gate)try{File.WriteAllText(Path.Combine(Directory,name),Diagnostics.Redact(Util.Json().Serialize(data)),new UTF8Encoding(false));}catch(Exception ex){Diagnostics.Error("diagnostic.write_error",ex);}}
  void WriteError(Exception ex){if(writeError!=null)return;writeError=ex.Message;Diagnostics.WriteError(ex);}
  public void Stderr(string value){if(!Enabled)return;lock(gate)try{ffmpeg.WriteLine(Diagnostics.Redact(value));}catch(Exception ex){WriteError(ex);}}
  public void Frame(int index,double approximate,double difference,double area,double dark,double luminance,bool black,bool generic,bool restored){if(!Enabled)return;lock(gate)try{metrics.WriteLine(string.Join(",",new[]{(index+1).ToString(),index.ToString(),Util.Num(approximate),Util.Num(difference),Util.Num(area),Util.Num(dark),Util.Num(luminance),black?"1":"0",generic?"1":"0",restored?"1":"0"}));if(index%50==0)metrics.Flush();}catch(Exception ex){WriteError(ex);}}
  public void Decision(string rule,int start,int end,bool accepted,string reason,object values=null){if(!Enabled)return;lock(gate)try{decisions.WriteLine(Diagnostics.Redact(Util.Json().Serialize(new {Rule=rule,StartFrame=start+1,EndFrame=end+1,StartIndex=start,EndIndex=end,Accepted=accepted,Reason=reason,Values=values})));}catch(Exception ex){WriteError(ex);}}
  public void Complete(AnalysisResult result){if(!Enabled)return;Meta("analysis.json",new DiagnosticAnalysis{File=result.Path,Id=Id,Info=result.Info,Settings=settings,FrameCount=result.FrameCount,EstimatedTimes=result.EstimatedTimes,Findings=result.Findings.ToArray(),Notice=result.Notice});lock(gate)try{using(var times=Diagnostics.Writer(Path.Combine(Directory,"frame-times.csv"))){times.WriteLine("FrameNumber,FrameIndex,Seconds");for(int i=0;i<result.Times.Count;i++)times.WriteLine((i+1)+","+i+","+Util.Num(result.Times[i]));}}catch(Exception ex){Diagnostics.Error("diagnostic.write_error",ex);}Flush();Diagnostics.Finished(this,writeError==null?"已完成":"已完成，日志不完整："+writeError,result.FrameCount);}
  public void Fail(Exception error,bool cancelled){if(!Enabled)return;Meta("failure.json",new {Cancelled=cancelled,Error=error.ToString(),Utc=DateTime.UtcNow.ToString("o")});Flush();Diagnostics.Finished(this,cancelled?"已取消":"失败",0);}
  public void Flush(){lock(gate){if(disposed)return;try{if(metrics!=null)metrics.Flush();if(decisions!=null)decisions.Flush();if(ffmpeg!=null)ffmpeg.Flush();}catch(Exception ex){WriteError(ex);}}}
  public void Dispose(){lock(gate){if(disposed)return;disposed=true;try{if(metrics!=null)metrics.Dispose();}catch(Exception ex){WriteError(ex);}try{if(decisions!=null)decisions.Dispose();}catch(Exception ex){WriteError(ex);}try{if(ffmpeg!=null)ffmpeg.Dispose();}catch(Exception ex){WriteError(ex);}}}
 }
}
